from stockflow.on_hand_by_location import on_hand_by_location
from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location


def cycle_count_variance(lines: Iterable[str], case_sizes: Mapping[str, int], counts: Mapping[Tuple[str, str], int]) -> List[Tuple[str, str, int]]:
    """
    Compare a cycle count with system stock and report the differences.
    """
    norm_counts: Dict[Tuple[str, str], int] = {}
    for (sku, loc), qty in counts.items():
        if qty < 0:
            raise ValueError("Counted quantity cannot be negative")
        k = (normalize_sku(sku), parse_location(loc))
        norm_counts[k] = norm_counts.get(k, 0) + qty

    sys_stock = on_hand_by_location(lines, case_sizes)
    counted_locs = {loc for (_, loc) in norm_counts.keys()}

    loc_to_skus: Dict[str, Set[str]] = {loc: set() for loc in counted_locs}
    for (sku, loc) in sys_stock.keys():
        if loc in counted_locs: loc_to_skus[loc].add(sku)
    for (sku, loc) in norm_counts.keys():
        if loc in counted_locs: loc_to_skus[loc].add(sku)

    results = []
    for loc in counted_locs:
        for sku in sorted(loc_to_skus[loc]):
            v = norm_counts.get((sku, loc), 0) - sys_stock.get((sku, loc), 0)
            if v != 0:
                results.append((sku, loc, v))

    return sorted(results, key=lambda x: (x[1], x[0]))"}}, "messages": []}

